    let sql = 'CREATE TABLE YourTableName (\n';

    for (let key in schema) {
        let field = schema[key];
        let fieldType = field.type;
        let sqlType = '';

        if (fieldType === 'string') {
            if (field.maxLength >= 255) {
                sqlType = 'TEXT';
            } else {
                sqlType = `VARCHAR(255)`;
            }
        } else if (fieldType === 'number') {
